// show the points
function showCurve(num = 1) {
	push()
	strokeWeight(1)
	noFill();

	// show dashed lines
	if (false) {		
		stroke(128, 64); 
		// stroke(112, 0, 16, 128)
		// drawingContext.setLineDash([10]);
		beginShape()
		for (let p of points) {
			vertex(p.x * width / 2, p.y * height / 2)
		}
		endShape(CLOSE)
	}

	// show curved lines
	stroke(32, 160); 
	if (false)
		for (let i = 0; i < num; i++) {
			const d = 15;
			const jitArr = [];
			for (let p of points) jitArr.push({x: randomGaussian(p.x * width/2, d), y: randomGaussian(p.y * height/2, d)})
			beginShape()
			for (let i = 0; i < jitArr.length + 3; i++) {
				p = jitArr[i % jitArr.length];
				curveVertex(p.x, p.y);
			}
			endShape()
		}

	stroke(32); 
	const shapeEdges = ~~random(2, 6); // line, triangle, rect or pentaeder
	let shapeAng = random(TWO_PI);
	const shDeltaAng = 0.1;
	for (let i = 0; i < num; i++) {
		var d = 15;
		var jitArr = [];
		for (let p of points) jitArr.push({x: randomGaussian(p.x * width/2, d), y: randomGaussian(p.y * height/2, d)})
		for (let i = 0; i < jitArr.length; i++) {
			const p1 = jitArr[(i+0) % jitArr.length];
			const p2 = jitArr[(i+1) % jitArr.length];
			const p3 = jitArr[(i+2) % jitArr.length];
			const p4 = jitArr[(i+3) % jitArr.length];
			const dst = dist(p2.x, p2.y, p3.x, p3.y);
			for (let f = 0; f < 1; f += 15/dst) {
				var x = curvePoint(p1.x, p2.x, p3.x, p4.x, f);
				var y = curvePoint(p1.y, p2.y, p3.y, p4.y, f);
				push()
				translate(x, y);
				// rotate(shapeAng += shDeltaAng); // constant angle rotation
				rotate(noise(12.3+x/123,23.4+y/213)*TWO_PI); // rotation by noise
				nShape(0, 0, 20, shapeEdges); // nShape(x, y, 20, 3)
				pop()
			}
		}
	}

	// show primary points
	if (false) {		
		strokeWeight(8)
		stroke(112, 0, 16, 128)
		for (let p of points) {
			point(p.x * width / 2, p.y * height / 2)
		}
	}

	pop()
}


function nShape(x, y, r, n=3) {
		beginShape();
		for (let i = 0; i <= n; i++) {
			const a = i/n*TWO_PI;
			const dx = cos(a) * r;
			const dy = sin(a) * r;
			vertex(x+dx, y+dy)
		}
		endShape()
}

// init curved points as structure for bars
function initCurvedCircle(numC = 2) {
	// init basic points 
	pnoise = [];
	const pdev = 0.2;
  const pmin = pdev;
  const pmax = 1- pdev;
  pnoise.push(new PNoise(-pmin, -pmax)); // x

  for (let i = 0; i < numC; i++) {
    pnoise.push(new PNoise(pmin, pmax)); // y
    pnoise.push(new PNoise(pmin, pmax)); // x
    pnoise.push(new PNoise(-pmin, -pmax)); // y
    pnoise.push(new PNoise(-pmin, -pmax)); // x
  }

	// init primary points x: -1...1, y: -1...1
  points = [];
  pos = 0;
  var x, y;
  let idx = 0;
  x = random(-pmin, -pmax);
  if (usePNoise) x = pnoise[idx++].getVal();
  for (let i = 0; i < numC; i++) {
    y = random(pmin, pmax);
    if (usePNoise) y = pnoise[idx++].getVal();
    points.push({ x, y });
    x = random(pmin, pmax);
    if (usePNoise) x = pnoise[idx++].getVal();
    // y = random(0.25, 0.75);
    points.push({ x, y });
    // x = random(0.25, 0.75);
    y = random(-pmin, -pmax);
    if (usePNoise) y = pnoise[idx++].getVal();
    points.push({ x, y });
    x = random(-pmin, -pmax);
    if (usePNoise) x = pnoise[idx++].getVal();
    // y = random(-0.25, -0.75);
    points.push({ x, y });
  }
	// adjust x-coord of last anchor point to first
  points[points.length - 1].x = points[0].x;

	// generate bars based on intermediate points on the curve
	if (true) return;
  bars = [];
	sbars = []; // [0.0,0.0,0.7,0.0];
  const sz = 40;
  const dt = (sz / max(width, height)) * 2;
	curveTightness(0); // needed for WEBGL
  for (let i = 0; i < points.length; i++) {
    // const t = (frameCount % fR) / fR;
    for (let t = 0; t < 1; t += dt) {
      const pa = points[(i - 2 + points.length) % points.length];
      const pb = points[(i - 1 + points.length) % points.length];
      const pc = points[(i + points.length) % points.length];
      const pd = points[(i + 1 + points.length) % points.length];
      const cx = curvePoint(pa.x, pb.x, pc.x, pd.x, t);
      const cy = curvePoint(pa.y, pb.y, pc.y, pd.y, t);
      const tx = curveTangent(pa.x, pb.x, pc.x, pd.x, t);
      const ty = curveTangent(pa.y, pb.y, pc.y, pd.y, t);
      const angle = atan2(ty, tx); //  - PI / 2.0;
      // for P2D: 1 entry per bar
			bars.push(new Bar(cx, cy, sz, 6, random(clrs), angle));
			bars[bars.length-1].act = true;
			// for WebGL: 4 entries per bar
			sbars.push(cx)
			sbars.push(cy)
			sbars.push(0.75)
			sbars.push(angle)
    }
  }

	// reduce num bars for WebGL
	if (webglVersion !== "p2d") {
		const redNum = 200; // adjust, when shader has a limit
		bars.splice(redNum, Infinity)
		sbars.splice(redNum * 4, Infinity) 
	}

  const da = TWO_PI / bars.length / 100;
  for (let pn of pnoise) {
    pn.da = da;
  }
}
